#!/usr/bin/env python3
"""Modern climate data analysis for Python 3.

Reads the station data and configuration that ship with the legacy
``climate_analyzer`` project and reports the mean temperature per station.
"""

from __future__ import annotations

import configparser
from pathlib import Path

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
DATA_DIR = BASE_DIR / "climate_analyzer"
DEFAULT_CSV = DATA_DIR / "sample_data" / "climate_data.csv"
DEFAULT_CONFIG = DATA_DIR / "config.ini"


class ClimateAnalyzer:
    """Load climate observations and compute per-station statistics."""

    def __init__(
        self,
        config_path: Path | str = DEFAULT_CONFIG,
        data_path: Path | str = DEFAULT_CSV,
    ) -> None:
        self.config_path = Path(config_path)
        self.data_path = Path(data_path)
        self.config = configparser.ConfigParser()
        self.config.read(self.config_path, encoding="utf-8")

    def load_temperature_data(self) -> pd.DataFrame:
        """Load observations from a UTF-8 encoded CSV file."""
        return pd.read_csv(
            self.data_path,
            encoding="utf-8",
            parse_dates=["date"],
        )

    def station_means(self, data: pd.DataFrame) -> pd.Series:
        """Return the mean temperature for every station in ``data``."""
        return data.groupby("station_id")["temperature"].mean()

    def run_analysis(self) -> None:
        """Print the mean temperature for each station."""
        data = self.load_temperature_data()
        for station_id, mean_temperature in self.station_means(data).items():
            print(
                f"Station {station_id} mean temperature: "
                f"{mean_temperature:.1f}\N{DEGREE SIGN}C"
            )


def main() -> None:
    ClimateAnalyzer().run_analysis()


if __name__ == "__main__":
    main()

